import { IngestPipeline } from "@514labs/moose-lib";

// User activity event data model
export interface UserActivity {
  eventId: string;
  eventTs: Date;
  userId: string;
  action: string;
  durationMs: number; // Will default to 0 for nulls during ingestion
}

// Create ingestion pipeline optimized for our query patterns
export const UserActivityPipeline = new IngestPipeline<UserActivity>("UserActivity", {
  table: {
    // Order by userId first for user-based queries, then eventTs for date ranges,
    // then action for action-type aggregations
    orderByFields: ["userId", "eventTs", "action"]
  },
  stream: true,
  ingestApi: true,
});

const fs = require('fs');
const csv = require('csv-parse');

// This script demonstrates how to ingest the CSV data through Moose API
// In a normal setup, this would POST to http://localhost:4000/ingest/UserActivity

async function ingestUserActivity() {
  const csvData = fs.readFileSync('/data/samples/user_activity_sample.csv', 'utf8');

  // Parse CSV data
  const records = [];
  csv.parse(csvData, {
    columns: true,
    skip_empty_lines: true
  }, (err, data) => {
    if (err) {
      console.error('Error parsing CSV:', err);
      return;
    }

    // Transform data to match our schema
    const transformedData = data.map(row => ({
      eventId: row.event_id,
      eventTs: new Date(row.event_ts),
      userId: row.user_id,
      action: row.action,
      durationMs: row.duration_ms ? parseFloat(row.duration_ms) : 0
    }));

    console.log('Sample record:', transformedData[0]);
    console.log(`Total records: ${transformedData.length}`);

    // In a real scenario, you would POST each record or batch to:
    // POST http://localhost:4000/ingest/UserActivity
    transformedData.forEach((record, index) => {
      console.log(`Record ${index + 1}:`, JSON.stringify(record));
    });
  });
}

// Uncomment to run:
// ingestUserActivity();

module.exports = { ingestUserActivity };
